    const db = await openDb();
    const rec =
      (await reqAsPromise<MetaRecord | undefined>(
        db.transaction("lix-blob").objectStore("lix-blob").get("current"),
      )) ?? null;
    const v = rec?.value;
    if (v instanceof Blob) return v;
