 * Fish Audio speaks through its own API, not an OpenAI-compatible one:
 * `POST /v1/tts`, the model in a `model:` header rather than the body, and the
 * voice selected by `reference_id` (a voice-model id from their library)
 * rather than by a name like "alloy".
 *
 * Because Fish requires a reference voice id, persona-specific Fish ids are
 * forwarded when they look like one. A writer using Fish directly must put a
 * 32-character model id in the Voice field in Settings.
 */
async function runFishAudioSpeech(args: {
  provider: AiProviderConfig;
  model: string;
  text: string;
  voice: string;
  responseFormat: string;
  speed?: number;
}): Promise<VoiceSpeechResult | null> {
  // Fish voice ids are 32-character hex; the OpenAI voice names we default to
  // ("alloy", "onyx", …) are not, and sending one would 422.
  const referenceId = /^[0-9a-f]{32}$/i.test(args.voice)
    ? args.voice
    : undefined;
  if (!referenceId) {
    throw new Error(
      "Fish Audio needs a 32-character reference voice id in Voice Narration settings.",
    );
  }
  const format = ["mp3", "wav", "pcm", "opus"].includes(args.responseFormat)
    ? args.responseFormat
    : "mp3";

  try {
    const res = await fetch(`${FISH_AUDIO_BASE}/v1/tts`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${args.provider.apiKey}`,
        "content-type": "application/json",
        model: args.model,
      },
      body: JSON.stringify({
        text: args.text,
        format,
        ...(referenceId ? { reference_id: referenceId } : {}),
        ...(args.speed ? { prosody: { speed: args.speed } } : {}),
      }),
    });
    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      throw new Error(
        `Fish Audio speech failed (${res.status}): ${detail.slice(0, 240)}`,
      );
    }
    return {
      audio: new Blob([await res.arrayBuffer()], {
        type: audioMimeType(format),
      }),
      provider: "fishaudio",
      model: args.model,
      voice: referenceId ?? "default",
      responseFormat: format,
    };
  } catch (err) {
    reportApplicationDiagnostic("twyne:ai-client:fishaudio-speech", err);
    throw err;
  }
}

/**
 * Fish Audio transcribes via `POST /v1/asr` as multipart form data — not the
 * OpenAI `/audio/transcriptions` shape, and with no `model` field in the body.
 */
async function runFishAudioTranscribe(args: {
  provider: AiProviderConfig;
  model: string;
  audio: Blob;
}): Promise<VoiceTranscribeResult | null> {
  try {
    const form = new FormData();
    form.append("audio", args.audio, `note.${blobExtension(args.audio.type)}`);
    form.append("ignore_timestamps", "true");

    const res = await fetch(`${FISH_AUDIO_BASE}/v1/asr`, {
      method: "POST",
      headers: { authorization: `Bearer ${args.provider.apiKey}` },
      body: form,
    });

 * Pick the voice name for whichever provider will actually serve this request.
 * Falls back to the generic name when the provider has no specific entry, and
 * to nothing at all when there is no provider — in which case the synthesis
 * call is about to fail anyway.
 */
export function pickVoiceForProvider(
  voices: Partial<Record<AiProviderType, string>> | undefined,
  fallback: string | undefined,
  providerType: AiProviderType | undefined,
): string | undefined {
  if (providerType && voices?.[providerType]) return voices[providerType];
  return fallback;
}

function resolveVoice(req: SpeakRequest, settings: AiSettings): string | undefined {
  return pickVoiceForProvider(
    req.voices,
    req.voice,
    resolveFeatureConfig(settings, "voice-narration")?.provider.type,
  );
}

/**
 * Fill in the voice fields from the cast when the caller knows only a name.
 *
 * Read fresh rather than memoised: the writer can rename or revoice an editor
 * mid-session, and one IndexedDB read is nothing beside the synthesis call it
 * precedes.
 */
async function withPersonaVoice(req: SpeakRequest): Promise<SpeakRequest> {
  if (!req.author) return req;
  if (req.voice && req.voices && req.instructions) return req;

  const name = req.author.trim().toLowerCase();
  if (!name) return req;

  let cast: Persona[] = PERSONAS;
  try {
    const custom = await loadPersonasFromIdb();
    if (custom && custom.length > 0) cast = custom;
  } catch {
    // The defaults still carry voices; a failed read is not worth a silence.
  }

  const persona = cast.find((p) => p.name.trim().toLowerCase() === name);
  if (!persona) return req;

  return {
    ...req,
    voice: req.voice ?? persona.speechVoice,
    voices: req.voices ?? persona.speechVoices,
    instructions: req.instructions ?? persona.voice,
  };
}

/** Stop whatever is playing. Safe to call when nothing is. */
export function stopSpeech(): void {
  generation += 1;
  if (audio) {
    audio.pause();
    audio.currentTime = 0;
  }
  setState("idle", null);
}

type Synthesis = {
  audio: Blob;
  provider: string;
  model: string;
  voice: string;
};

/**
 * Get generated audio for a passage.
 *
 * A configured BYOK voice provider is authoritative: its selected provider
 * and model are used, and failures are surfaced rather than silently changing
 * models. Hosted speech is considered only when no BYOK voice provider exists.
 */
async function synthesize(req: SpeakRequest): Promise<Synthesis> {
  const text = req.text.trim();
  const settings = await getCachedAiSettings();

  // Gate on a *voice-capable* provider, not a language one: a writer may have
  // Fish Audio configured for speech and nothing else, and a writer may have
  // Anthropic configured for the room but nothing that can speak.
  if (hasConfiguredVoiceProvider(settings)) {
    const result = await runClientVoiceSpeech(
      { text, voice: resolveVoice(req, settings), instructions: req.instructions },
      settings,
    );
    if (result) {
      return {
        audio: result.audio,
        provider: result.provider,
        model: result.model,
        voice: result.voice,
      };
    }
    const selected = resolveFeatureConfig(settings, "voice-narration");
    throw createAppError("PROVIDER_ERROR", {
      source: "provider",
      metadata: {
        feature: "voice-narration",
        operation: "synthesize",
        provider: selected?.provider.type,
        model: selected?.model,
      },
    });
  }

  if (req.client && req.signedIn) {
    try {
      const res = (await req.client.action(api.voice.synthesizeSpeech, {
        text,
        voice: req.voice,
        instructions: req.instructions,
      })) as { audioBase64: string; mimeType: string };
      const bytes = Uint8Array.from(atob(res.audioBase64), (c) =>
        c.charCodeAt(0),
      );
      return {
        audio: new Blob([bytes], { type: res.mimeType }),
        provider: "hosted",
        model: "hosted",
        voice: req.voice ?? "alloy",
      };
    } catch (err) {
      reportApplicationDiagnostic("twyne:speech:hosted-declined", err, {
        feature: "voice-narration",
      });
      throw err;
    }
  }

  throw createAppError("CONFIGURATION_ERROR", {
    source: "application",
    recovery: { action: "choose-provider", canRetry: false },
    metadata: { feature: "voice-narration", operation: "synthesize" },
  });
}

