              if (res && res.text.trim() && res.provider !== "local") {
                replyText = res.text;
              } else {
                store.askError = commentProviderError("ask-editor");
                return;
              }
            } catch (err) {
              store.askError = normalizeCommentError(
                "twyne:comments:ask-editor-client",
                err,
                "provider",
                "ask-editor",
